import { ArrowRight, Check, ChevronLeft, ChevronRight, Eye, FileImage, Film, Folder, Image as ImageIcon, LayoutDashboard, Lock, LogOut, Mail, Menu, MoreHorizontal, Play, Plus, Search, Settings, Shield, UploadCloud, User, X } from 'lucide-react'
